-- Applies the French translations to rows that already exist (the seed does
-- the same for fresh databases). Merged into `translations`, matched on the
-- natural key, and safe to run on any environment: rows that aren't there are
-- simply not touched.

UPDATE "Country" SET "translations" = COALESCE("translations", '{}'::jsonb) || $q${"fr":{"name":"Sénégal"}}$q$::jsonb WHERE "name" = $q$Senegal$q$;
