UPDATE "Notification" SET "messageKey" = 'registrationOpen' WHERE "messageKey" IS NULL AND "title" = $q$Registration is open$q$ AND "body" = $q$Dakar Open Amateur starts in a week — grab your spot.$q$;
UPDATE "Notification" SET "messageKey" = 'niceWin' WHERE "messageKey" IS NULL AND "title" = $q$Nice win!$q$ AND "body" = $q$Your last match earned you season points. See where you stand.$q$;
